const NL = String.fromCharCode(10);
const raw = items[0] ? items[0].json : {};
const stdout = String(raw.stdout || '').trim();
const stderr = String(raw.stderr || '').trim();
const sshError = raw.error ? String(raw.error.message || raw.error) : '';
const limpiar = (v) => String(v === null || v === undefined ? '' : v).replace(/[<>&]/g, ' ');
const ahora = new Date().toLocaleString('es-BO', { timeZone: 'America/La_Paz', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
let h = null;
try {
  const a = stdout.indexOf('{');
  const b = stdout.lastIndexOf('}');
  if (a >= 0 && b > a) h = JSON.parse(stdout.slice(a, b + 1));
} catch (e) { h = null; }
const PIE = NL + 'Detectado: ' + ahora + ' (el chequeo corre cada 10 min, o sea empezo hace 10 min o menos)' + NL + 'Ver estado: /opt/onia/bot/webhook-server.sh status' + NL + 'Ver logs:   /opt/onia/bot/webhook-server.sh logs 50';
let alert = false;
let motivo = 'ok';
let texto = '';
if (sshError || !stdout || !h) {
  alert = true;
  motivo = 'sin_respuesta';
  const detalle = sshError || stderr || stdout || '(sin salida)';
  texto = 'BOT DE WHATSAPP CAIDO' + NL + NL + 'El chequeo no devolvio un estado legible. Nadie esta atendiendo a quien escriba al +591 75414930.' + NL + NL + 'Salida cruda: ' + limpiar(detalle).slice(-400) + NL + PIE;
} else if (h.db && h.db.ok !== true) {
  // VA ANTES que el chequeo de `ok`: con la base caida `ok` tambien es false, y el texto generico
  // diria "no recibe respuesta", que es MENTIRA — el bot contesta igual. Este es el modo de falla
  // que costo 5 dias en agosto sin que nadie se enterara.
  alert = true;
  motivo = 'db_caida';
  texto = 'EL BOT CONTESTA PERO NO GUARDA NADA' + NL + NL + 'La base no responde. El bot sigue respondiendo de memoria, asi que desde afuera parece sano, pero: cada mensaje reinicia la conversacion desde cero, un reintento de Chatwoot le manda la misma respuesta DOS VECES al prospecto, y NINGUN lead esta llegando al CRM.' + NL + NL + 'Error: ' + limpiar(h.db.error || 'sin detalle') + NL + 'Latencia: ' + limpiar(h.db.latencyMs === undefined ? '?' : h.db.latencyMs) + ' ms' + NL + NL + 'Revisar primero: el firewall entre contenedores (la regla ONIA-BLOCK-3000 corta el puerto de PostgREST), y que supabase-rest y supabase-kong esten arriba.' + NL + PIE;
} else if (h.ok !== true) {
  alert = true;
  motivo = 'ok_false';
  const razon = h.reason ? h.reason : ((h.auth && h.auth.aviso) ? h.auth.aviso : 'sin motivo declarado');
  texto = 'BOT DE WHATSAPP NO ESTA ATENDIENDO' + NL + NL + 'El servidor respondio ok:false. Quien escriba al +591 75414930 no recibe respuesta.' + NL + NL + 'Motivo: ' + limpiar(razon) + NL + PIE;
} else if (((h.knowledge || {}).source) !== 'file') {
  alert = true;
  motivo = 'knowledge_no_file';
  const k = h.knowledge || {};
  texto = 'EL BOT PERDIO LA CAPA DE CONOCIMIENTO' + NL + NL + 'El bot responde, pero volvio a los valores del CODIGO: lo que se edito en knowledge.json NO se esta aplicando a lo que contesta.' + NL + NL + 'knowledge.source: ' + limpiar(k.source || '(ausente)') + '  (deberia ser: file)' + NL + 'Version cargada: ' + limpiar(k.version || 'sin version') + NL + (k.loadedAt ? 'Cargada el: ' + limpiar(k.loadedAt) + NL : '') + (k.lastError ? 'Ultimo error: ' + limpiar(k.lastError) + NL : '') + 'Reaplicar: /opt/onia/bot/webhook-server.sh knowledge' + NL + PIE;
}
return [{ json: { alert: alert, motivo: motivo, ok: h ? h.ok === true : false, db: (h && h.db) ? h.db.ok === true : null, source: (h && h.knowledge) ? h.knowledge.source : null, text: texto.slice(0, 3900) } }];
